TEMPERATURE_UNITS = {"c", "celsius", "deg c", "degree c", "f", "fahrenheit", "deg f", "k", "kelvin"}
LENGTH_UNITS = {"m", "meter", "meters", "km", "kilometer", "kilometers", "ft", "feet", "nmi", "nm", "nautical mile", "nautical miles"}
