    TEMPERATURE = "TEMPERATURE"
    CONCENTRATION_MASS_VOLUME = "CONCENTRATION_MASS_VOLUME"
    CONCENTRATION_MIXING_RATIO = "CONCENTRATION_MIXING_RATIO"
    PRECIPITATION = "PRECIPITATION"
    FLOW = "FLOW"
    VOLUME = "VOLUME"
    DISTANCE = "DISTANCE"
    AREA = "AREA"
    MASS = "MASS"
    PRESSURE = "PRESSURE"
    DIMENSIONLESS = "DIMENSIONLESS"
    INDEX = "INDEX"
    COUNT = "COUNT"
    TIME = "TIME"
    UNKNOWN = "UNKNOWN"


