def new_id(prefix: str) -> str:
    return f"{prefix}_{uuid.uuid4().hex[:12]}"


def utcnow() -> datetime:
    return datetime.now(timezone.utc)


def _json_default(obj: Any) -> Any:
    if isinstance(obj, Enum):
        return obj.value
    if isinstance(obj, datetime):
        return obj.isoformat()
    return str(obj)


def safe_float(value: Any) -> Optional[float]:
    if value is None or value == "":
        return None
    try:
        return float(value)
    except Exception:
        return None


def normalize_whitespace(value: Any) -> str:
    if value is None:
        return ""
    return " ".join(str(value).split())


def normalize_text(value: Any, upper: bool = False) -> Optional[str]:
    if value is None:
        return None
    s = unicodedata.normalize("NFKC", str(value)).strip()
    if not s:
        return None
    return s.upper() if upper else s


def to_datetime(value: Any) -> Optional[datetime]:
    if value is None:
        return None

    if isinstance(value, datetime):
        dt = value
    elif isinstance(value, (int, float)):
        try:
            dt = datetime.fromtimestamp(float(value), tz=timezone.utc)
        except Exception:
            return None
    elif isinstance(value, str):
        s = value.strip()
        if not s:
            return None
        s = s.replace("Z", "+00:00")
        try:
            dt = datetime.fromisoformat(s)
        except Exception:
            dt = None
            for fmt in (
                "%Y-%m-%dT%H:%M:%S%z",
                "%Y-%m-%dT%H:%M:%S",
                "%Y-%m-%d %H:%M:%S",
                "%Y/%m/%d %H:%M:%S",
                "%Y-%m-%d",
            ):
                try:
                    dt = datetime.strptime(s, fmt)
                    break
                except Exception:
                    continue
            if dt is None:
                return None
    else:
        return None

    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.astimezone(timezone.utc)


def enum_from(cls, value: Any, default: Any) -> Any:
    if isinstance(value, cls):
        return value
    try:
        return cls(str(value).upper())
    except Exception:
        try:
            return cls(str(value))
        except Exception:
            return default


def unique_list(items: Iterable[Any]) -> List[Any]:
    seen = set()
    out = []
    for item in items:
        if item is None:
            continue
        key = item.value if isinstance(item, Enum) else item
        if key not in seen:
            seen.add(key)
            out.append(item)
    return out


def mean(values: Iterable[Optional[float]]) -> Optional[float]:
    vals = [v for v in values if v is not None]
    if not vals:
        return None
    return sum(vals) / len(vals)


def median(values: Iterable[Optional[float]]) -> Optional[float]:
    vals = sorted(v for v in values if v is not None)
    if not vals:
        return None
    n = len(vals)
    mid = n // 2
    if n % 2 == 1:
        return vals[mid]
    return (vals[mid - 1] + vals[mid]) / 2.0


def std(values: Iterable[Optional[float]]) -> Optional[float]:
    vals = [v for v in values if v is not None]
    if len(vals) < 2:
        return 0.0
    m = sum(vals) / len(vals)
    var = sum((x - m) ** 2 for x in vals) / (len(vals) - 1)
    return math.sqrt(var)


def clamp(x: float, lo: float, hi: float) -> float:
    return max(lo, min(hi, x))


def sha256_text(value: str) -> str:
    return hashlib.sha256(value.encode("utf-8")).hexdigest()


def hash_payload(payload: Any) -> str:
    try:
        canonical = json.dumps(payload, sort_keys=True, default=_json_default)
    except Exception:
        canonical = str(payload)
    return sha256_text(canonical)


def tokens(text: str) -> List[str]:
    return re.findall(r"[a-z0-9]+", (text or "").lower())


def token_set(text: str) -> set[str]:
    return {t for t in re.split(r"\W+", (text or "").lower()) if t}


def shingles(text: str, k: int = 5) -> set[Tuple[str, ...]]:
    ts = tokens(text)
    if not ts:
        return set()
    if len(ts) < k:
        return {tuple(ts)}
    return {tuple(ts[i:i + k]) for i in range(len(ts) - k + 1)}


def jaccard(a: set[Any], b: set[Any]) -> float:
    if not a or not b:
        return 0.0
    return len(a & b) / len(a | b)


def similarity(a: str, b: str) -> float:
    return difflib.SequenceMatcher(None, (a or "").lower(), (b or "").lower()).ratio()


def canonical_url(url: Optional[str]) -> str:
    if not url:
        return ""
    try:
        p = urlparse(url)
        scheme = "https" if p.scheme in ("http", "https", "") else p.scheme
        netloc = p.netloc.lower()
        if netloc.startswith("www."):
            netloc = netloc[4:]
        path = p.path.rstrip("/")
        if path.endswith("/amp"):
            path = path[:-4]

        tracking_prefixes = ("utm_",)
        tracking_exact = {
            "fbclid",
            "gclid",
            "mc_cid",
            "mc_eid",
            "igshid",
            "ref",
            "source",
            "s",
            "cmpid",
            "campaign",
        }

        query = []
        for k, v in parse_qsl(p.query, keep_blank_values=True):
            lk = k.lower()
            if lk.startswith(tracking_prefixes) or lk in tracking_exact:
                continue
            if lk == "outputtype" and v.lower() == "amp":
                continue
            query.append((k, v))

        return urlunparse((scheme, netloc, path, p.params, urlencode(query), ""))
    except Exception:
        return normalize_whitespace(url)


def detect_language(text: str, declared: Optional[str] = None) -> str:
    if declared:
        return declared.strip().upper()
    if not text:
        return "UNKNOWN"
    for ch in text:
        cp = ord(ch)
        if 0x0600 <= cp <= 0x06FF:
            return "AR"
        if 0x0400 <= cp <= 0x04FF:
            return "RU"
        if 0x4E00 <= cp <= 0x9FFF:
            return "ZH"
        if 0x0900 <= cp <= 0x097F:
            return "HI"
        if 0xAC00 <= cp <= 0xD7AF:
            return "KO"
        if 0x00C0 <= cp <= 0x024F:
            return "LATIN_EXTENDED"
    return "EN"


def excerpt(text: str, limit: int = 220) -> str:
    s = normalize_whitespace(text)
    if len(s) <= limit:
        return s
    return s[: limit - 1].rstrip() + "…"


def fmt_dt(value: Optional[datetime]) -> str:
    return value.isoformat() if value else "UNKNOWN"


def parse_number(raw: str, multiplier: Optional[str] = None) -> Optional[float]:
    try:
        value = float(raw.replace(",", ""))
    except Exception:
        return None
    mult = (multiplier or "").lower()
    if mult == "thousand":
        value *= 1_000
    elif mult == "million":
        value *= 1_000_000
    elif mult == "billion":
        value *= 1_000_000_000
    return value


